CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations (id text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK (role='owner'), created_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), event_type text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), ip_hash text);
CREATE TABLE IF NOT EXISTS instruments (code text PRIMARY KEY, display_name text NOT NULL, price_precision integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS market_candles (id bigserial PRIMARY KEY, instrument text NOT NULL REFERENCES instruments(code), timeframe text NOT NULL, close_time timestamptz NOT NULL, open numeric NOT NULL, high numeric NOT NULL, low numeric NOT NULL, close numeric NOT NULL, volume bigint NOT NULL, source text NOT NULL CHECK(source='oanda'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(instrument,timeframe,close_time,source));
CREATE TABLE IF NOT EXISTS quote_snapshots (id bigserial PRIMARY KEY, instrument text NOT NULL REFERENCES instruments(code), observed_at timestamptz NOT NULL, bid numeric NOT NULL, ask numeric NOT NULL, spread_pips numeric NOT NULL, source text NOT NULL CHECK(source='oanda'));
CREATE TABLE IF NOT EXISTS market_data_ingestion_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, details jsonb NOT NULL DEFAULT '{}'::jsonb, error text);
CREATE TABLE IF NOT EXISTS strategy_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, version text NOT NULL, configuration jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(name,version));
CREATE TABLE IF NOT EXISTS strategy_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), strategy_version_id uuid NOT NULL REFERENCES strategy_versions(id), instrument text NOT NULL REFERENCES instruments(code), decision_time timestamptz NOT NULL, source_kind text NOT NULL CHECK(source_kind IN ('historical','forward')), status text NOT NULL, direction text, entry numeric, stop numeric, target numeric, risk_reward numeric, spread_pips numeric, conditions jsonb NOT NULL, candle_cutoff timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(strategy_version_id,instrument,decision_time,source_kind));
CREATE TABLE IF NOT EXISTS evaluation_features (evaluation_id uuid PRIMARY KEY REFERENCES strategy_evaluations(id) ON DELETE CASCADE, feature_version text NOT NULL, features jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS trade_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evaluation_id uuid UNIQUE NOT NULL REFERENCES strategy_evaluations(id) ON DELETE CASCADE, status text NOT NULL, raw_units numeric, applied_units numeric, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outcome_labels (candidate_id uuid PRIMARY KEY REFERENCES trade_candidates(id) ON DELETE CASCADE, outcome text NOT NULL CHECK(outcome IN ('target_first','stop_first','unresolved','ambiguous')), labeled_at timestamptz NOT NULL DEFAULT now(), horizon_ends_at timestamptz NOT NULL, result_r numeric, max_favorable_r numeric, max_adverse_r numeric);
CREATE TABLE IF NOT EXISTS paper_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL REFERENCES users(id), balance numeric NOT NULL DEFAULT 10000, currency text NOT NULL DEFAULT 'USD', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS paper_trades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), legacy_id text, origin text NOT NULL, pair text NOT NULL, direction text NOT NULL, status text NOT NULL, result text NOT NULL, opened_at timestamptz NOT NULL, closed_at timestamptz, entry numeric NOT NULL, stop numeric NOT NULL, target numeric NOT NULL, exit numeric, result_r numeric, reason text NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,legacy_id));
CREATE TABLE IF NOT EXISTS paper_trade_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), paper_trade_id uuid NOT NULL REFERENCES paper_trades(id) ON DELETE CASCADE, event_type text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS research_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, details jsonb NOT NULL DEFAULT '{}'::jsonb, error text);
CREATE INDEX IF NOT EXISTS strategy_evaluations_research_idx ON strategy_evaluations (decision_time DESC, instrument, source_kind);
CREATE INDEX IF NOT EXISTS paper_trades_user_idx ON paper_trades (user_id, opened_at DESC);
